<?php
namespace Azuriom\Plugin\GamingHubCore\Settings;
use Azuriom\Models\Setting; use Azuriom\Plugin\GamingHubCore\Services\NormalizedDataKeys; use Illuminate\Support\Facades\Cache;
final class PublicDataSettings { public const PREFIX='gaming-hub-core.public-data.'; public const DEFAULT_VISIBLE=['server.state'=>true,'server.message'=>true,'server.version'=>false,'server.name'=>false,'players.current'=>true,'players.maximum'=>true,'resources.cpu_percent'=>false,'resources.memory_used_bytes'=>false,'resources.memory_limit_bytes'=>false,'resources.disk_used_bytes'=>false,'uptime.seconds'=>false,'observed_at'=>false,'source_updated_at'=>false]; public function global(string $key):array{$d=self::DEFAULT_VISIBLE[$key]??false;return ['visible'=>$this->bool(self::PREFIX.$key.'.visible',$d),'attribution'=>$this->bool(self::PREFIX.$key.'.attribution',false)];} public function all():array{$r=[];foreach(NormalizedDataKeys::GENERIC as $k)$r[$k]=$this->global($k);return $r;} public function save(array $input):void{$v=[];foreach(NormalizedDataKeys::GENERIC as $k){$v[self::PREFIX.$k.'.visible']=$this->input($input,'visible',$k);$v[self::PREFIX.$k.'.attribution']=$this->input($input,'attribution',$k);}Setting::updateSettings($v);Cache::forget('settings');Cache::forget('azuriom.settings');} private function bool(string $k,bool $d):bool{$v=setting($k,$d);if(is_bool($v))return $v;if(is_numeric($v))return (int)$v===1;if(is_string($v))return in_array(strtolower(trim($v)),['1','true','yes','on'],true);return $d;} private function input(array $a,string $group,string $key):bool{$v=$a[$group][$key]??false;return filter_var($v,FILTER_VALIDATE_BOOL);}}
